#!/usr/bin/env python3
"""Extract first-page text from all PDF files for classification."""
import os
import glob
import json
from PyPDF2 import PdfReader

def extract_first_text(pdf_path, max_chars=3000):
    try:
        reader = PdfReader(pdf_path)
        text = ""
        # Read first 2 pages
        for i, page in enumerate(reader.pages[:2]):
            try:
                page_text = page.extract_text() or ""
                text += page_text + "\n"
                if len(text) >= max_chars:
                    break
            except Exception as e:
                text += f"[ERR page {i}: {e}]\n"
        return text[:max_chars]
    except Exception as e:
        return f"[ERROR: {e}]"

results = {}
for pdf in sorted(glob.glob("*.pdf")):
    text = extract_first_text(pdf)
    results[pdf] = text

with open("_pdf_titles.json", "w") as f:
    json.dump(results, f, indent=2)

# Print summary
print(f"Total: {len(results)} PDFs")
for pdf in sorted(results.keys()):
    preview = results[pdf].replace("\n", " ").strip()[:200]
    print(f"{pdf}: {preview[:150]}...")

